def old_0051_enableSellerBuying(apps, schemaEditor):
    profiles = apps.get_model('storefront', 'Profile').objects.using(schemaEditor.connection.alias)
    profiles.filter(canSell=True, user__is_staff=False).update(canBuy=True)


